<?php
 namespace Pterodactyl\Services\Dezerx\Minecraft; use Pterodactyl\Models\Server; use Illuminate\Support\Facades\Http; use Illuminate\Support\Facades\Cache; use Pterodactyl\Services\Dezerx\Addons; class BlueMap { private const RELEASES = 'https://api.github.com/repos/BlueMap-Minecraft/BlueMap/releases/latest'; private const VERSIONS = 'https://api.modrinth.com/v2/project/%s/version'; private const PROJECT = 'bluemap'; private const DEPENDENCY = 'fabric-api'; private const AGENT = 'Pterodactyl-Panel/1.0 (bluemap installer)'; private const VERSION_DIRECTORIES = ['/versions', '/libraries/net/fabricmc/intermediary', '/libraries/net/minecraft/server']; private const MAX_LOG = 16_384; public const RELEASE_JAR = '/^bluemap-\d[\w.+]*-(paper|spigot|fabric|forge|neoforge|sponge)\.jar$/i'; private const TTL = 3600; public const STATUS_TTL = 300; public const PORT_TTL = 300; public const PORT_TTL_MISSING = 30; public const TOKEN_TTL = 21_600; private const TOKEN = '/^[a-f0-9]{48}$/'; public static function minecraft(ServerFiles $files): ?string { $installed = InstalledVersion::read($files)['version'] ?? null; if (is_string($installed) && self::isVersion($installed)) { return $installed; } foreach (self::VERSION_DIRECTORIES as $directory) { $found = null; foreach ($files->listFiles($directory) ?? [] as $entry) { $name = (string) ($entry['name'] ?? ''); if (self::isVersion($name) && ($found === null || version_compare($name, $found, '>'))) { $found = $name; } } if ($found !== null) { return $found; } } return self::fromLog($files); } private static function fromLog(ServerFiles $files): ?string { $log = $files->fileContents('/logs/latest.log', self::MAX_LOG); if ($log === null) { return null; } return preg_match('/(?:Loading Minecraft|minecraft server version)\s+(\d+\.\d+(?:\.\d+)?)/i', $log, $found) === 1 ? $found[1] : null; } public static function release(string $platform, ?string $minecraft = null): ?array { if ($minecraft !== null) { $catalogue = self::catalogue($platform); if ($catalogue !== null) { return self::pick($catalogue, $minecraft); } } return self::latest($platform); } public static function dependency(string $platform, ?string $minecraft): ?array { if ($platform !== 'fabric' || $minecraft === null) { return null; } $catalogue = self::versions(self::DEPENDENCY, 'fabric'); return $catalogue === null ? null : self::pick($catalogue, $minecraft); } public static function catalogue(string $platform): ?array { return self::versions(self::PROJECT, $platform); } private static function versions(string $project, string $loader): ?array { $key = "dezerx:bluemap:versions:{$project}:{$loader}"; $cached = Cache::get($key); if (is_array($cached)) { return $cached; } $response = Http::withHeaders(['User-Agent' => self::AGENT]) ->timeout(20) ->get(sprintf(self::VERSIONS, $project), ['loaders' => json_encode([$loader])]); if ($response->failed()) { return null; } $versions = []; foreach ($response->json() ?? [] as $entry) { $file = self::file($entry['files'] ?? []); if ($file === null) { continue; } $number = (string) ($entry['version_number'] ?? ''); $versions[] = $file + [ 'version' => str_ends_with($number, "-{$loader}") ? mb_substr($number, 0, -mb_strlen($loader) - 1) : $number, 'stable' => ($entry['version_type'] ?? '') === 'release', 'published' => (string) ($entry['date_published'] ?? ''), 'minecraft' => array_map('strval', $entry['game_versions'] ?? []), ]; } Cache::put($key, $versions, self::TTL); return $versions; } private static function pick(array $versions, string $minecraft): ?array { $matches = array_values(array_filter( $versions, fn (array $version) => in_array($minecraft, $version['minecraft'], true), )); if ($matches === []) { return null; } usort($matches, fn (array $a, array $b) => [$b['stable'], $b['published']] <=> [$a['stable'], $a['published']]); return $matches[0]; } private static function file(array $files): ?array { foreach ([true, false] as $primaryOnly) { foreach ($files as $file) { $name = (string) ($file['filename'] ?? ''); $url = (string) ($file['url'] ?? ''); if ($url === '' || !str_ends_with(mb_strtolower($name), '.jar')) { continue; } if ($primaryOnly && !($file['primary'] ?? false)) { continue; } return ['url' => $url, 'filename' => $name]; } } return null; } private static function latest(string $platform): ?array { $latest = Cache::remember('dezerx:bluemap:latest', self::TTL, function () { $response = Http::withHeaders(['User-Agent' => self::AGENT]) ->timeout(20) ->get(self::RELEASES); if ($response->failed()) { return null; } return [ 'tag' => (string) ($response->json('tag_name') ?? ''), 'assets' => array_map(fn (array $asset) => [ 'name' => (string) ($asset['name'] ?? ''), 'url' => (string) ($asset['browser_download_url'] ?? ''), ], $response->json('assets') ?? []), ]; }); if ($latest === null) { Cache::forget('dezerx:bluemap:latest'); return null; } foreach ($latest['assets'] as $asset) { if (str_ends_with($asset['name'], "-{$platform}.jar")) { return [ 'url' => $asset['url'], 'filename' => $asset['name'], 'version' => $latest['tag'], ]; } } return null; } private static function isVersion(string $value): bool { return preg_match('/^\d+\.\d+(\.\d+)?$/', $value) === 1; } public static function configDirectory(string $platform): string { return ServerPlatform::isPlugin($platform) ? '/plugins/BlueMap' : '/config/bluemap'; } public static function configure(ServerFiles $files, string $platform, int $port): bool { $directory = self::configDirectory($platform); $files->createDirectory($directory); $core = <<<'CONF'
            # Written by the panel when BlueMap was installed.
            accept-download: true
            data: "bluemap"
            render-thread-count: 1
            scan-for-mod-resources: true
            metrics: false
            CONF; $webserver = <<<CONF
            # Written by the panel when BlueMap was installed.
            enabled: true
            webroot: "bluemap/web"

            # Must be the allocation the panel claimed, and must bind to all
            # interfaces - the container's own address is not reachable.
            ip: "0.0.0.0"
            port: {$port}
            max-connection-count: 100
            CONF; return $files->writeFile("{$directory}/core.conf", $core) && $files->writeFile("{$directory}/webserver.conf", $webserver); } public static function jars(ServerFiles $files, string $directory, string $pattern = '/^bluemap.*\.jar$/i'): array { $names = []; foreach ($files->listFiles($directory) ?? [] as $entry) { $name = (string) ($entry['name'] ?? ''); if (preg_match($pattern, $name) === 1) { $names[] = $name; } } return $names; } public static function installed(ServerFiles $files, string $directory): ?string { return self::jars($files, $directory)[0] ?? null; } public static function address(ServerFiles $files): ?array { $detected = ServerPlatform::detect($files); if ($detected === null) { return null; } $conf = $files->fileContents(self::configDirectory($detected['platform']).'/webserver.conf'); if ($conf === null || preg_match('/^\s*port:\s*(\d+)/m', $conf, $match) !== 1) { return null; } $port = (int) $match[1]; foreach ($files->allocations() as $allocation) { if ($allocation['port'] === $port) { return ['ip' => $allocation['ip'], 'port' => $port]; } } return null; } public static function cachedAddress(ServerFiles $files): ?array { $key = self::portKey($files->server->uuid); $cached = Cache::get($key); if (is_array($cached)) { return $cached === [] ? null : $cached; } $address = self::address($files); Cache::put($key, $address ?? [], $address === null ? self::PORT_TTL_MISSING : self::PORT_TTL); return $address; } public static function token(Server $server, int $user): string { $key = "dezerx:bluemap-session:{$server->uuid}:{$user}"; $token = Cache::get($key); if (!is_string($token) || preg_match(self::TOKEN, $token) !== 1) { $token = bin2hex(random_bytes(24)); } Cache::put($key, $token, self::TOKEN_TTL); Cache::put("dezerx:bluemap-token:{$token}", $server->uuid, self::TOKEN_TTL); return $token; } public static function resolve(string $token): ?Server { if (preg_match(self::TOKEN, $token) !== 1) { return null; } $uuid = Cache::get("dezerx:bluemap-token:{$token}"); if (!is_string($uuid)) { return null; } $server = Server::query()->where('uuid', $uuid)->first(); if ($server === null || $server->isSuspended() || !Addons::appliesTo(Addons::WORLD_VIEWER, $server)) { return null; } return $server; } public static function portKey(string $server): string { return "dezerx:bluemap-port:{$server}"; } public static function forget(string $server): void { Cache::forget(self::portKey($server)); Cache::forget("dezerx:bluemap:{$server}"); } } 